import{Z as t,e as s,f as i,a0 as a}from"./chunks/framework.DmpHOl9T.js";const m=JSON.parse('{"title":"Translations","description":"","frontmatter":{},"headers":[],"relativePath":"forms/translations.md","filePath":"forms/translations.md","lastUpdated":1782306980000}'),o={name:"forms/translations.md"};function r(n,e,l,d,h,p){return s(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="translations" tabindex="-1">Translations <a class="header-anchor" href="#translations" aria-label="Permalink to &quot;Translations&quot;">​</a></h1><p>Formie handles text on forms in three separate ways. Each has its own purpose — form copy from the builder, Formie-owned UI strings, and project-level developer strings.</p><h2 id="three-layers" tabindex="-1">Three Layers <a class="header-anchor" href="#three-layers" aria-label="Permalink to &quot;Three Layers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>What it covers</th><th>Where it lives</th></tr></thead><tbody><tr><td><strong>Form content</strong></td><td>Labels, placeholders, messages, option labels, notification copy</td><td>Form builder (database). Per-site wording via <a href="/forms/multi-site-and-translation#content-translation">site overrides</a> on multi-site projects.</td></tr><tr><td><strong>Formie static strings</strong></td><td>Validation templates, <code>(optional)</code>, file-upload prompts, payment UI labels</td><td><code>translations/{locale}/formie.php</code> and Formie’s bundled translation files</td></tr><tr><td><strong>Project strings</strong></td><td>Custom client event templates, developer-defined labels outside Formie forms</td><td><code>translations/{locale}/site.php</code></td></tr></tbody></table><p>Form content is <strong>not</strong> translated through Craft’s message system at render time. After site overrides are merged, Formie outputs the string from the database as-is.</p><h2 id="when-to-use-what" tabindex="-1">When to Use What <a class="header-anchor" href="#when-to-use-what" aria-label="Permalink to &quot;When to Use What&quot;">​</a></h2><h3 id="multi-site-form-copy" tabindex="-1">Multi-Site Form Copy <a class="header-anchor" href="#multi-site-form-copy" aria-label="Permalink to &quot;Multi-Site Form Copy&quot;">​</a></h3><p>Use the form builder <strong>site switcher</strong> and <a href="/forms/multi-site-and-translation#content-translation">content translation overrides</a>. This is the supported way to give each Craft site different labels or messages while sharing one form structure.</p><p>Site overrides are keyed by <strong>Craft site</strong>, not locale file. That matters when two sites share a language but need different wording — for example <code>en-US</code> and <code>en-AU</code> with different labels for the same field.</p><h3 id="single-site-projects" tabindex="-1">Single-Site Projects <a class="header-anchor" href="#single-site-projects" aria-label="Permalink to &quot;Single-Site Projects&quot;">​</a></h3><p>Write copy directly in the form builder. You do not need translation files for field labels or form messages.</p><p>Use <code>formie.php</code> only if you want to override Formie-owned UI strings (see below).</p><h3 id="formie-owned-strings-formie-category" tabindex="-1">Formie-Owned Strings (<code>formie</code> Category) <a class="header-anchor" href="#formie-owned-strings-formie-category" aria-label="Permalink to &quot;Formie-Owned Strings (\`formie\` Category)&quot;">​</a></h3><p>Use <code>translations/{locale}/formie.php</code> for strings Formie owns — strings passed to <code>Craft::t(&#39;formie&#39;, &#39;…&#39;)</code> with a fixed English source key in the plugin.</p><p>Examples:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// translations/de/formie.php</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;{label} cannot be blank.&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{label} darf nicht leer sein.&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;(optional)&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;(optional)&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;Are you sure you want to leave?&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Möchten Sie die Seite wirklich verlassen?&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;Drop files here or browse to upload.&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Dateien hier ablegen oder zum Hochladen durchsuchen.&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span></code></pre></div><p>These keys must match the <strong>English source string</strong> in the plugin exactly. Formie does not use separate message IDs.</p><p>Front-end JavaScript validation messages are seeded from the same strings via <code>Rendering::getFrontendJsTranslations()</code>. Override them in <code>formie.php</code> the same way.</p><h3 id="project-strings-site-category" tabindex="-1">Project Strings (<code>site</code> Category) <a class="header-anchor" href="#project-strings-site-category" aria-label="Permalink to &quot;Project Strings (\`site\` Category)&quot;">​</a></h3><p>Use <code>translations/{locale}/site.php</code> for your own plugin, module, or template strings — not for form field labels created in the Formie builder.</p><p>Formie uses <code>site</code> in a few places for Craft element names (for example site names in the builder site switcher). That follows Craft conventions for project-level copy.</p><h2 id="what-does-not-belong-in-translation-files" tabindex="-1">What Does Not Belong in Translation Files <a class="header-anchor" href="#what-does-not-belong-in-translation-files" aria-label="Permalink to &quot;What Does Not Belong in Translation Files&quot;">​</a></h2><p>Do <strong>not</strong> put form builder content in <code>formie.php</code> or <code>site.php</code>:</p><ul><li>Field labels, instructions, placeholders</li><li>Page labels and submit/back/save button labels</li><li>Dropdown, radio, or checkbox option labels</li><li>Success, error, limit, or scheduling messages</li><li>Notification subject or body edited in the form builder</li></ul><p>Field labels and form messages belong in the form builder (or <a href="/forms/multi-site-and-translation#content-translation">site overrides</a> on multi-site projects), not in translation files. If your project still has entries like <code>&#39;Your name&#39; =&gt; &#39;Votre nom&#39;</code> in <code>formie.php</code>, move that wording into the builder — see <a href="/get-started/upgrading-from-v3#form-content-translations">Upgrading From v3 → Form content translations</a>.</p><h2 id="multi-site-vs-static-files" tabindex="-1">Multi-Site vs Static Files <a class="header-anchor" href="#multi-site-vs-static-files" aria-label="Permalink to &quot;Multi-Site vs Static Files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Approach</th><th>Per Craft site</th><th>Editor-managed</th><th>Same language, different sites</th></tr></thead><tbody><tr><td>CP site overrides</td><td>Yes</td><td>Yes</td><td>Yes</td></tr><tr><td><code>formie.php</code></td><td>No (per locale only)</td><td>No (deploy)</td><td>No</td></tr></tbody></table><p>For multi-site forms, prefer CP overrides. Static <code>formie.php</code> files remain the right place for plugin UI strings only.</p><h2 id="rendering-behaviour" tabindex="-1">Rendering Behaviour <a class="header-anchor" href="#rendering-behaviour" aria-label="Permalink to &quot;Rendering Behaviour&quot;">​</a></h2><p>When a form is rendered — via Twig, GraphQL, or the React bootstrap — Formie:</p><ol><li>Loads the canonical form from the form’s source site.</li><li>Merges <a href="/forms/multi-site-and-translation#content-translation">site overrides</a> for the current site when multi-site is enabled.</li><li>Outputs user-authored strings without passing them through <code>Craft::t()</code>.</li></ol><p>Plugin-owned strings (validation defaults, required indicators, upload prompts) still use <code>Craft::t(&#39;formie&#39;, …)</code> and your locale’s <code>formie.php</code> overrides.</p><p>Submissions load forms with the same site override merge, so notifications and exports use the wording for the submission’s site.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>French site shows English field labels</strong></p><p>You need French <a href="/forms/multi-site-and-translation#example-translating-a-contact-form">site overrides</a> in the form builder, not entries in <code>formie.php</code>.</p><p><strong>German source site shows English labels</strong></p><p>Check the canonical labels on the source site in the builder. Form content is stored and output as written.</p><p><strong>Validation messages stay in English</strong></p><p>Add overrides to <code>translations/{locale}/formie.php</code> for the English source keys (for example <code>{label} cannot be blank.</code>), or set plugin-wide defaults under <strong>Formie → Settings → Defaults</strong>.</p><p><strong>Two English sites need different labels</strong></p><p>Use CP site overrides. A single <code>translations/en/formie.php</code> file cannot distinguish between Craft sites.</p>`,42)])])}const g=t(o,[["render",r]]);export{m as __pageData,g as default};
